using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
namespace ClearSpace {
public sealed partial class Controller {
 async Task VerifyRulePacks(string output,Action<bool,string> check){
  var options=new CleanerSettings();int saves=0;UiText.SetLanguage("zh-CN");
  await WithSettings(options,null,root=>{var ini=(CheckBox)root.FindName("EnableWinapp2");var json=(CheckBox)root.FindName("EnableJson");var provider=(ComboBox)root.FindName("RuleProvider");var automatic=(CheckBox)root.FindName("Automatic");var save=(Button)root.FindName("Save");check(ini.IsChecked==true&&json.IsChecked==false,"Rule controls preserve legacy enabled-source defaults");json.IsChecked=true;check(!options.JsonEnabled&&saves==0,"Draft enable switches do not affect the scanner before saving");automatic.IsChecked=true;provider.SelectedIndex=1;check(ini.IsChecked==true&&json.IsChecked==true&&automatic.IsChecked==false,"Source editor changes preserve both enabled switches and separate automatic settings");((TextBox)root.FindName("UpdateUrl")).Text="https://example.test/rules.json";automatic.IsChecked=true;save.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(options.Winapp2Enabled&&options.JsonEnabled&&options.AutoWinapp2&&options.AutoJson&&saves==1,"Saving persists simultaneous sources with independent automatic updates");provider.SelectedIndex=0;check(automatic.IsChecked==true&&options.JsonEnabled,"Returning to the Winapp2 editor leaves JSON enabled");App.Render(Window,Path.Combine(output,"rules-together.png"));},value=>saves++);
  string directory=Path.Combine(output,"pack-ui-fixture");var store=new RulePackCatalog(Path.Combine(directory,"definitions"));store.Import(RulePackTests.Raw());var fixture=Path.Combine(directory,"Cache");Directory.CreateDirectory(fixture);string file=Path.Combine(fixture,"old.log");File.WriteAllText(file,"preview fixture");File.SetLastWriteTimeUtc(file,DateTime.UtcNow.AddDays(-60));var rule=new Rule("library-preview-fixture","Fixture cache","软件缓存","","",new[]{fixture},30,false){ForceBackup=true};
  var entered=new TaskCompletionSource<bool>();using(var gate=new ManualResetEventSlim(false)){
   try{int changed=0,notices=0;rulePackView=RulePackCenter.Create(Window,options,new DiscoveryResult(),BackPage,()=>changed++,text=>notices++,text=>notices++,store);var root=rulePackView.Root;PushPage(root);var list=(ListBox)root.FindName("PackList");var enabled=(CheckBox)root.FindName("PackEnabled");var preview=(Button)root.FindName("PackPreview");var progress=(ProgressBar)root.FindName("PackProgress");var details=(TextBox)root.FindName("PackDetails");check(list.Items.Count==1&&enabled.IsChecked==false&&preview.IsEnabled,"Installed packs are selectable for preview even while disabled");enabled.IsChecked=true;enabled.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(store.List().Single().Enabled&&changed==1&&notices==1,"Pack enable switches persist immediately and report success");App.Render(Window,Path.Combine(output,"rule-packs-dark.png"));
    RulePackCenter.PreviewFixture=(pack,apps,token,pulse)=>{pulse(new ScanProgress{Completed=0,Total=1,Title="Fixture cache"});entered.TrySetResult(true);while(!gate.Wait(10))token.ThrowIfCancellationRequested();token.ThrowIfCancellationRequested();return new Engine(new List<Rule>{rule}){IsRunning=owners=>false}.Scan(token,null);};preview.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await entered.Task;await Task.Delay(30);check(progress.Visibility==Visibility.Visible&&!list.IsEnabled&&preview.Content.ToString()=="取消预览","Read-only preview has visible progress, cancellation and locked pack changes");int pagesBefore=pages.Count;BackPage();check(pages.Count==pagesBefore&&!NavigationCanClose(),"Leaving an active preview cancels it before removing the page");
    for(int i=0;i<300&&preview.Content.ToString()!="只读预览";i++)await Task.Delay(10);check(preview.Content.ToString()=="只读预览"&&File.Exists(file)&&list.IsEnabled&&progress.Visibility==Visibility.Collapsed,"Cancelled preview restores controls and keeps its cache file");
    gate.Set();preview.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));for(int i=0;i<300&&preview.Content.ToString()!="只读预览";i++)await Task.Delay(10);check(details.Text.Contains(file)&&((TextBlock)root.FindName("PackPreviewStatus")).Text.Contains("未删除文件")&&File.Exists(file),"Completed preview shows matched paths and explicitly reports no deletion");
    UiTheme.Set("light",false);UiText.SetLanguage("en");App.Render(Window,Path.Combine(output,"rule-packs-light-english.png"));check(preview.Content.ToString()=="Read-only preview"&&((Button)root.FindName("PackImport")).Content.ToString()=="Import rule pack","Pack actions follow English localization and the current theme");BackPage();check(rulePackView==null&&pages.Count==0,"Pack back navigation returns to cleanup and releases its close guard");
   }finally{gate.Set();RulePackCenter.PreviewFixture=null;UiText.SetLanguage("zh-CN");UiTheme.Set("dark",false);if(rulePackView==null||rulePackView.TryLeave())while(pages.Count>0)BackPage();}
  }
 }
}
}
